package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;

import java.io.IOException;

import org.eclipse.kura.KuraException;
import org.junit.Test;

import com.github.dockerjava.api.model.EventType;

public class EnforcementLifecycleTest extends AbstractEnforcementTest {

    @Test
    public void startingEnforcementSubscribesToContainerLifecycleEvents() {
        whenEnforcementStarts();

        thenContainerStartAndRemovalEventsAreSubscribed();
    }

    @Test
    public void notStartedEnforcementDoesNotCheckContainers() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenDigestRegisteredBy(OTHER_CONTAINER_ID, IMAGE_DIGEST);

        whenDigestIsUnregisteredBy(OTHER_CONTAINER_ID);

        thenNoContainerWasDeleted();
    }

    @Test
    public void closedEnforcementDoesNotCheckContainers() throws KuraException {
        givenStartedEnforcement();
        givenClosedEnforcement();
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenDigestRegisteredBy(OTHER_CONTAINER_ID, IMAGE_DIGEST);

        whenDigestIsUnregisteredBy(OTHER_CONTAINER_ID);

        thenNoContainerWasDeleted();
    }

    @Test
    public void enforcementThatFailedToCloseDoesNotCheckContainers() throws KuraException {
        givenEventStreamFailsToClose();
        givenStartedEnforcement();
        givenClosedEnforcement();
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenDigestRegisteredBy(OTHER_CONTAINER_ID, IMAGE_DIGEST);

        whenDigestIsUnregisteredBy(OTHER_CONTAINER_ID);

        thenNoContainerWasDeleted();
    }

    @Test
    public void runningContainersAreCheckedWhenTheFirstConnectionFails() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenNextConnectionFails();

        whenEnforcementStarts();

        thenContainerWasDeleted(CONTAINER_ID);
    }

    @Test
    public void unexpectedSubscriptionErrorLeavesEnforcementInactive() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenSubscriptionsThrowUnexpectedly();

        whenEnforcementStarts();

        thenNoContainerWasDeleted();
    }

    private void givenEventStreamFailsToClose() {
        this.events.failClosingWith(new IOException("connection to docker lost"));
    }

    private void givenSubscriptionsThrowUnexpectedly() {
        this.events.failSubscriptionsWith(new IllegalStateException("unexpected client error"));
    }

    private void thenContainerStartAndRemovalEventsAreSubscribed() {
        verify(this.events.command(), times(1)).withEventTypeFilter(EventType.CONTAINER);
        verify(this.events.command(), times(1)).withEventFilter("start", "destroy", "remove");
        thenEventsWereSubscribed(1);
    }
}
